CREATE TABLE "message_edits" (
	"position" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "message_edits_position_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"message_id" text NOT NULL,
	"channel_id" text NOT NULL,
	"kind" text NOT NULL,
	"previous_body" text NOT NULL,
	"edited_by" text NOT NULL,
	"edited_at" text NOT NULL,
	CONSTRAINT "message_edit_kind" CHECK ("message_edits"."kind" IN ('edit', 'withdraw'))
);
