-- A message stays where and by whom it was said: its author may change the
-- body or withdraw it (which is final), and nothing is ever deleted.
DROP TRIGGER messages_immutable ON messages;--> statement-breakpoint
CREATE TRIGGER messages_immutable BEFORE DELETE ON messages
  FOR EACH ROW EXECUTE FUNCTION kinmesh_refuse('immutable communication fact');--> statement-breakpoint
CREATE TRIGGER message_identity_immutable BEFORE UPDATE ON messages
  FOR EACH ROW WHEN (OLD.withdrawn_at IS NOT NULL
    OR (NEW.position, NEW.id, NEW.channel_id, NEW.topic_id, NEW.author, NEW.created_at,
        NEW.source_message_id, NEW.source_event_id)
    IS DISTINCT FROM (OLD.position, OLD.id, OLD.channel_id, OLD.topic_id, OLD.author,
        OLD.created_at, OLD.source_message_id, OLD.source_event_id))
  EXECUTE FUNCTION kinmesh_refuse('immutable communication fact');--> statement-breakpoint
-- What a message said before is kept as it was written.
CREATE TRIGGER message_edits_immutable BEFORE UPDATE OR DELETE ON message_edits
  FOR EACH ROW EXECUTE FUNCTION kinmesh_refuse('immutable communication fact');--> statement-breakpoint
CREATE TRIGGER message_edits_announce AFTER INSERT ON message_edits
  FOR EACH STATEMENT EXECUTE FUNCTION kinmesh_announce();
